/// <summary>
/// CB411_412_ChargeThrough Service item lookup
/// </summary>
[ExtensionOf(classStr(InventItemIdLookupSimple))]
final class METInventItemIdLookupSimpleCls_Extension
{
}

Method.Source:
/// <summary>
/// Configures the lookup for a given extended data type.
/// </summary>
/// <param name = "_typeName">The name of the extended data type.</param>
protected void configureByExtendedDataTypeName(ExtendedDataTypeName _typeName)
{
    next configureByExtendedDataTypeName(_typeName);
    
    switch (_typeName)
    {
        case extendedTypeStr(METChargeThroughServiceItemId):
        case extendedTypeStr(METCrossDockServiceItemId):
            this.METFilterOnlyService();
            break;            
    }
}

/// <summary>
/// Filter service items only
/// </summary>
void METFilterOnlyService()
{
    inventItemIdLookupSimpleViewQbds.addRange(fieldNum(InventItemIdLookupSimpleView, ItemType)).value(queryValue(ItemType::Service));
}
